<?php
namespace App\Http\Controllers\Admin; use App\Domain\Articles\{ArticleManager,ArticleViewData}; use App\Domain\Installation\WebsiteSettings; use App\Http\Controllers\{Controller,PublicSiteController}; use App\Http\Requests\Articles\SaveArticleRequest; use App\Models\{Article,ArticleCategory}; use Illuminate\Contracts\View\View; use Illuminate\Http\{RedirectResponse,Request,Response}; use Illuminate\Support\Carbon; use Illuminate\Validation\Rule;
class ArticleController extends Controller { public function index(Request $r):View{$f=$r->validate(['search'=>['nullable','string','max:160'],'status'=>['nullable',Rule::in(['draft','published','scheduled','archived'])],'featured'=>['nullable','in:0,1'],'archived'=>['nullable','in:with,only,without']]);$q=Article::with('category')->when($f['search']??null,fn($q,$v)=>$q->where(fn($q)=>$q->where('title','like',"%$v%")->orWhere('slug','like',"%$v%")))->when($f['status']??null,fn($q,$v)=>$q->where('status',$v))->when(isset($f['featured']),fn($q)=>$q->where('is_featured',(bool)$f['featured']));if(($f['archived']??'without')==='only'){$q->whereNotNull('archived_at');}elseif(($f['archived']??'without')==='without'){$q->whereNull('archived_at');}return view('admin.articles.index',['items'=>$q->orderBy('display_order')->paginate(20)->withQueryString()]);} public function create():View{return $this->editor(new Article);} public function store(SaveArticleRequest $r,ArticleManager $m):RedirectResponse{$x=$m->save($r->validated(),null,$r->user()->id);return redirect()->route('admin.articles.edit',$x);} public function edit(Article $article):View{return $this->editor($article);} public function update(SaveArticleRequest $r,Article $article,ArticleManager $m):RedirectResponse{$m->save($r->validated(),$article,$r->user()->id);return back()->with('status','Saved.');} private function editor(Article $item):View{return view('admin.articles.editor',['item'=>$item,'categories'=>ArticleCategory::where('is_active',true)->orderBy('display_order')->get()]);} public function publish(Article $article,ArticleManager $m):RedirectResponse{$m->publish($article);return back();} public function schedule(Request $r,Article $article,ArticleManager $m):RedirectResponse{$v=$r->validate(['scheduled_for'=>['required','date']]);$tz=app(WebsiteSettings::class)->current()?->timezone?:'UTC';$m->schedule($article,Carbon::parse($v['scheduled_for'],$tz)->utc()->toDateTimeString());return back();} public function unpublish(Article $article,ArticleManager $m):RedirectResponse{$m->unpublish($article);return back();} public function archive(Article $article,ArticleManager $m):RedirectResponse{$m->archive($article);return back();} public function restore(Article $article,ArticleManager $m):RedirectResponse{$m->restore($article);return back();} public function duplicate(Request $r,Article $article,ArticleManager $m):RedirectResponse{return redirect()->route('admin.articles.edit',$m->duplicate($article,$r->user()->id));} public function move(Article $article,string $direction,ArticleManager $m):RedirectResponse{$m->move($article,$direction);return back();} public function preview(Request $r,Article $article,ArticleViewData $d):Response{return response()->view('articles.show',['article'=>$d->preview($article),'preview'=>true]+app(PublicSiteController::class)->sharedViewData($r))->header('Cache-Control','no-store, private, max-age=0')->header('X-Robots-Tag','noindex, nofollow');} public function categories():View{return view('admin.articles.categories',['items'=>ArticleCategory::orderBy('display_order')->get()]);} public function storeArticleCategory(Request $r):RedirectResponse{$d=$r->validate(['name'=>['required','string','max:160'],'slug'=>['required','regex:/^[a-z0-9]+(?:-[a-z0-9]+)*$/','unique:article_categories,slug'],'description'=>['nullable','string','max:2000']]);$d['display_order']=(int)ArticleCategory::max('display_order')+1;$d['is_active']=true;ArticleCategory::create($d);return back();} }
